package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PhoneNumberVerifiedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property phone number verified of user profile ")
  void test_phone_number_verified_v_o_builder() {
    Assertions.assertFalse(PhoneNumberVerifiedVO.nullValue().isPhoneNumberVerified(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PhoneNumberVerifiedVO.tryFrom(null).isPhoneNumberVerified(),
        "With a null value, no present result");
    Assertions.assertEquals(true, PhoneNumberVerifiedVO.from(true).isPhoneNumberVerified());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> PhoneNumberVerifiedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", PhoneNumberVerifiedVO.from(true).toString());
  }
}
